local _, ns = ...

-- GENERATED by a local tool (not included in the repository). Do not edit by hand: use Data/Overrides.lua.

ns.AddQuests("hot", {
    { id = 96391, name = "Underground Map", level = 15, minLevel = 9, faction = "Alliance", finish = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, objective = "Deliver the Dark Iron Map to Earthseer Farsen in Dun Morogh.", desc = "<The map you are holding seems to show a complex series of underground tunnels and highways that all seem to converge on a point underneath Ironforge itself.\n\nYou can't be sure what the runes say as they are written in the ugly jagged rune language of the Dark Iron dwarves, but you can guess at the purpose of these tunnels. As you are reading the map, a gust of wind washes over you and you can faintly hear a dwarven voice carried on it. Earthseer Farsen needs to see this.>" }, -- ? (extra/series)
    { id = 96393, name = "Old Ironforge Incursion", level = 16, minLevel = 9, requires = { 96391 }, faction = "Alliance", giver = "Earthseer Farsen", start = { npc = "Earthseer Farsen", area = 1, x = 64.8, y = 58.4 }, finish = { npc = "King Magni Bronzebeard", area = 1537, x = 39.4, y = 55.8 }, dungeon = "hot", objective = "Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer.", desc = "Gather some allies and head down into the caverns beneath Old Ironforge. Enter the Hall of Thanes there and push to the lower vaults.\n\nMy Dark Iron is a bit rusty, but I can make out a name--one Durgen Dirgehammer. It's likely that he's the commander. Take his head and deliver it to King Magni Bronzebeard.\n\nOh, and when you do, tell him his old friend Farsen sends his regards!" }, -- Dungeon
    { id = 96394, name = "The Restless Dead", level = 15, minLevel = 10, faction = "Alliance", giver = "Afadra Dunwall", start = { npc = "Afadra Dunwall", area = 1537, x = 33, y = 48 }, finish = { npc = "Afadra Dunwall", area = 1537, x = 33, y = 48 }, dungeon = "hot", objective = "Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest.", desc = "Something has disturbed the tombs down in the Hall of Thanes, and strange noises have been heard coming from deep within the vaults. The spirits of the dead are light sleepers, and whatever is going on down there seems to have startled them.\n\nHead down there and see what you can do about that for us. If any of the dead are awake--well, put them back down!" }, -- Dungeon
    { id = 96395, name = "An Ancient Grudge", level = 15, minLevel = 10, dungeon = "hot", objective = "Put the spirit of Faldrim Anvilmar to rest and then return to the Ghostly Attendant in the Hall of Thanes.", desc = "The... Thane... my mighty... Thane... he... needs to... rest.\n\nPlease... help him... help him... rest...\n\nConsumed... by... ancient... grudge... No... rest..." }, -- Dungeon
    { id = 96403, name = "Important Heirlooms", level = 15, minLevel = 10, faction = "Alliance", giver = "Thom Filch", start = { npc = "Thom Filch", area = 1537, x = 32.4, y = 44.8 }, finish = { npc = "Thom Filch", area = 1537, x = 32.4, y = 44.8 }, dungeon = "hot", objective = "Collect 8 Dwarven Heirlooms from the Hall of Thanes.", desc = "You there, adventurer... I could really use your aid.\n\nI was sneaking--uh... 'patrolling' in the vaults when a force of Dark Iron dwarves emerged from the depths in mole machines! I don't know what they are here for, but there is priceless loot--uh or, rather... I mean, 'important cultural heirlooms' down there! Please, recover any such relics you see and return them here.\n\nI assure you that anything you recover will be catalogued and returned to its proper place of honor." }, -- Dungeon
})

ns.AddQuests("rol", {
    { id = 92401, name = "A Frightened Request", level = 22, minLevel = 15, faction = "Horde", giver = "Tabitha Heartweaver", start = { npc = "Tabitha Heartweaver", area = 130, x = 44.4, y = 42.8 }, finish = { npc = "Tabitha Heartweaver", area = 130, x = 44.4, y = 42.8 }, dungeon = "rol", objective = "Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron.", desc = "It's my husband Edward...\n\nHe has not returned from his weekly journey to the graveyard in the Lordaeron ruins. Our son was lost when Arthas razed the city, and my dear Edward is still filled with guilt and sorrow that we never found his body. I've tried to warn him against searching those overrun ruins, but he refuses to give up. I try not worry, but it's been days.\n\nThere are things there I cannot contend with but if you are willing, I need to know the fate of my husband." }, -- Dungeon (extra/series)
    { id = 92415, name = "Remember That I Love You (1/2)", level = 22, minLevel = 15, faction = "Alliance", finish = { npc = "Orphan Matron Nightingale", area = 1519, x = 56.2, y = 54.1 }, dungeon = "rol", objective = "Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City.", desc = "<A torn and stained bundle of parchment has barely survived the undead trodden grounds of the graveyard. It mentions a missing child of the Heartweaver family. Perhaps the orphan matron in Stormwind City will know more.>" }, -- Dungeon
    { id = 92421, name = "Light's Justice", level = 22, minLevel = 15, faction = "Horde", giver = "Morbin Lightbane", start = { npc = "Morbin Lightbane", area = 1497, x = 57.8, y = 89.8 }, finish = { npc = "Morbin Lightbane", area = 1497, x = 57.8, y = 89.8 }, dungeon = "rol", objective = "Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity.", desc = "As a paladin of the Forsaken, it is my duty to exact the will of our Dark Lady while tending to our people's needs. We are fortunate with an opportunity to accomplish both.\n\nAbove the Undercity, the scourge still roam unchecked in great numbers. Our forces dwindle trying to reclaim our land, and decaying flesh cannot be reknit. Not without replacements.\n\nWould that our glorious captain Garek Bandarion still be with us, I know what he would wish. To finish what he started and heal our kin. For Lordaeron!" }, -- Dungeon
    { id = 92422, name = "The Wrath of Rath'mael", level = 22, minLevel = 15, faction = "Horde", giver = "Deathguard Kristof", start = { npc = "Deathguard Kristof", area = 85, x = 65.2, y = 60.2 }, finish = { npc = "Deathguard Kristof", area = 85, x = 65.2, y = 60.2 }, dungeon = "rol", objective = "Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill.", desc = "Reports have come in from the Lordamere Overlook deep within the Ruins of Lordaeron. An unholy fog has taken over the streets and graveyard, affording the scourge up there some measure of stealth.\n\nOur scouts indicate they're being conjured by a new power within their ranks, a necromancer known as Rath'mael. We do not have the luxury of waiting this one out, <name>.\n\nIf you have allies, summon them and their aid to the Forsaken. Drive this creature out of our lands." }, -- Dungeon
    { id = 92432, name = "An Alarming Request", level = 33, minLevel = 30, faction = "Alliance", giver = "Emissary Jacques", start = { npc = "Emissary Jacques", area = 267, x = 48.3, y = 60.1 }, finish = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, desc = "I bring ill tidings from Dalaran. Something has disrupted our ley lines, causing erratic and destructive behavior from our constructs in the city.\n\nWe know not yet what is causing this mayhem. The high council has ordered us to keep this matter private so as to not bring shame to our order. But we cannot keep up this charade forever. The city is being overrun as we speak!\n\nArchmage Modera has dispatched me to solicit outside aid. Seek her image out near Dalaran beside Lordamere Lake." }, -- ? (extra/series)
    { id = 92434, name = "Blood in the Streets", level = 34, minLevel = 30, faction = "Horde", giver = "Magus Wordeen Voidglare", start = { npc = "Magus Wordeen Voidglare", area = 267, x = 61.6, y = 20.8 }, finish = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, objective = "Find a way into Dalaran along the Lordamere Lake.", desc = "Whatever caused Dalaran's barrier to lower has left the city in turmoil. With you having dealt with their patrols, there is no better time than now to make our way inside and discover their secrets.\n\nTake the key you found at the internment camp and seek out their sewers along the northern border of the city. With luck, those mages had no reason to put a ward over such a... disagreeable point of entry." }, -- ? (extra/series)
    { id = 92458, name = "Heart of Disruption", level = 33, minLevel = 24, requires = { 92432 }, faction = "Alliance", giver = "Image of Archmage Modera", start = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, dungeon = "rol", objective = "Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran.", desc = "Whatever disturbed the ley lines, it started at the top of the Violet Citadel. A thunderous crash rang out from the parlors above, and now we are overrun with rampant arcane power. It's taking all we have just to keep the wards in place.\n\nWe cannot afford to stall any longer. We need help.\n\nThe Kirin Tor are busy inside, but you will still need a less public approach to gain entry. Take this key and meet me in the citadel once you've made your way into the city. We must put an end to this disruption." }, -- Dungeon (extra/series)
    { id = 92459, name = "Friend of the Kirin Tor", level = 33, minLevel = 24, requires = { 92458 }, faction = "Alliance", objective = "Speak to Archmage Celindra in the City of Dalaran.", desc = "The council will not be happy to learn of our subterfuge, but they cannot deny results. The city is calming down, and we are free to lower our wards.\n\nI think it's only fair you deliver the good word. Take this mote to Archmage Celindra within the Violet Citadel." }, -- ?
    { id = 95161, name = "Remember That I Love You (2/2)", level = 22, minLevel = 15, requires = { 92415 }, faction = "Alliance", giver = "Orphan Matron Nightingale", start = { npc = "Orphan Matron Nightingale", area = 1519, x = 56.2, y = 54.1 }, finish = { npc = "Avette Fellwood", area = 10, x = 73.2, y = 44.8 }, objective = "Deliver the Blood-Stained Letter to Avette Fellwood in Duskwood.", desc = "If you're looking for Jeremy Heartweaver, your best bet is to talk to his newly adopted mother, Avette Fellwood out in Duskwood. Sweet woman. Likely needs another pair of hands for her work, but it beats staying in the orphanage.\n\nIf you see little Jeremy do be sure to tell him we're all thinking of him, won't you?" }, -- ? (extra/series)
    { id = 95189, name = "Crest of Lordaeron", level = 22, minLevel = 16, faction = "Alliance", finish = { npc = "Lady Dena Kennedy", area = 1519, x = 74, y = 47.5 }, dungeon = "rol", objective = "Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City.", desc = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in Stormwind would be very keen to get their hands on this.>" }, -- Dungeon
    { id = 95195, name = "Bloodied Insignia", level = 22, minLevel = 16, faction = "Alliance", finish = { npc = "General Marcus Jonathan", area = 1519, x = 69, y = 82.8 }, dungeon = "rol", objective = "Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City.", desc = "<The old Alliance insignia appears to have belonged to a soldier of Lordaeron. These ruins are likely filled with similar medals that living relatives would be grateful to have returned to them.>" }, -- Dungeon
    { id = 95204, name = "Crest of Lordaeron", level = 22, minLevel = 16, faction = "Horde", finish = { npc = "Oran Snakewrithe", area = 1497, x = 73.4, y = 32.4 }, dungeon = "rol", objective = "Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity.", desc = "<A weathered crest depicting the mark of Lordaeron. With so few relics left after the kingdom's fall, someone in the Undercity would be very keen to get their hands on this.>" }, -- Dungeon
    { id = 95216, name = "The New Plague", level = 22, minLevel = 16, faction = "Horde", giver = "Theodore Griffs", start = { npc = "Theodore Griffs", area = 1497, x = 46.6, y = 71.8 }, finish = { npc = "Theodore Griffs", area = 1497, x = 46.6, y = 71.8 }, dungeon = "rol", objective = "Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity.", desc = "Welcome to the most vital organ of the Undercity: The Apothecarium! Here we experiment on the most virulent of Azeroth's exotic specimens.\n\nYou've caught me in a good mood, so I will let you in on my latest investigation. It appears there is a particularly venomous arthropod stalking the ruins above our fair city. Its toxins are said to eat through even undead flesh. How exhilarating!\n\nI wish to validate these claims. Should you find yourself withering away from its bite, I should love a sample." }, -- Dungeon
    { id = 95250, name = "Abominable Creatures", level = 21, minLevel = 16, faction = "Alliance", dungeon = "rol", objective = "Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman.", desc = "What do you want, <race>? Can't you see there is a war to be won?\n\nMy master has already charged into the fray and has ordered me to maintain my post. It has been quite some time, however.\n\nI doubt you'll survive ten minutes in combat, but if it keeps your simple mind busy, why don't you seek out the Grand Marshal. He is the tallest, most statuesque hero you've ever laid eyes on. You'll know him when you see him." }, -- Dungeon
    { id = 96984, name = "Heart of Disruption", level = 33, minLevel = 24, requires = { 92434 }, faction = "Horde", giver = "Image of Archmage Modera", start = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, dungeon = "rol", objective = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", desc = "You may not have our best interests at heart, but I won't deny an extra pair of hands. And if Dalaran falls, it takes everything with it--including your Undercity.\n\nSo, your benefactor wants in? Fine. I'll imbue your key to work past my wards so you can enter the city. Once you're in, meet me at the Violet Citadel where this all began. With everything going on the Kirin Tor will be too busy to stop you.\n\nScavenge what you will, but whatever happens, our first priority is to prevent a catastrophe." }, -- Dungeon (extra/series)
    { id = 97287, name = "Shrewd Negotiations", level = 33, minLevel = 24, requires = { 96984 }, faction = "Horde", objective = "Speak with Archmage Celindra in the City of Dalaran.", desc = "You have done well to infiltrate the city of mages, but I believe it is time for us to be more... negotiatory.\n\nAs much as it pains me to admit, there is no other place on Azeroth with such a vast knowledge of the arcane. My brilliant work still pales in comparison to the ancient wisdom the Kirin Tor have amassed over the years. I think it's high time we are granted access to this exclusive order, don't you think?\n\nTake the mote you acquired. They will surely give anything to get it back. Anything." }, -- ?
    { id = 97288, name = "Unending Torment (1/5)", level = 21, minLevel = 16, faction = "Horde", finish = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, dungeon = "rol", objective = "Deliver the Abominable Head to Master Apothecary Faranell within the Undercity.", desc = "<As the creature falls, its head comes toppling off. It seems as if it has been reattached several times, and the connection gets weaker with each reconnection.\n\nSomeone in the Undercity would know more about this unique abomination.>" }, -- Dungeon
    { id = 97289, name = "Unending Torment (2/5)", level = 21, minLevel = 16, requires = { 97288 }, faction = "Horde", giver = "Master Apothecary Faranell", start = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, finish = { npc = "Unfinished Abomination", area = 1497, x = 46.2, y = 63 }, objective = "Bring the Head of the Baron to the body of Othmar in the Undercity.", desc = "We craft abomination heads all the time, but this one is special. It belonged to a Grand Marshal of the alliance once. A particularly unpleasant one. Othmar, I believe its name was. The Dark Lady had the pleasure of dispatching of this one herself.\n\nOoh the secrets it could tell if it could talk. And it can! If we reattach it to an appropriate host.\n\nGo ahead and place it next to the available body in the next room. But don't attach it. Not yet." }, -- ?
    { id = 97290, name = "Unending Torment (3/5)", level = 21, minLevel = 16, requires = { 97289 }, faction = "Horde", giver = "Unfinished Abomination", start = { npc = "Unfinished Abomination", area = 1497, x = 46.2, y = 63 }, finish = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, desc = "You... abomination...\n\nWhy should... help you...\n\nBe gone..." }, -- ? (extra/series)
    { id = 97291, name = "Unending Torment (4/5)", level = 21, minLevel = 16, requires = { 97290 }, faction = "Horde", giver = "Master Apothecary Faranell", start = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, finish = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, objective = "Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity.", desc = "With the head reattached, all we need now is to bind it to the Dark Lady's will. This should not be a problem. The beast barely has brains left as it is after all the beatings it's taken.\n\nWe simply need to motivate it.\n\nFetch me a Toxic Skullcap from Miss Grisette in the Trade Quarter. Oh, and some Blisterweed from our local herbalist trainers, the Alliestars. Feel free to just take some, they owe me. And lastly a bit of Essence of Agony. Any old poison vendor should do.\n\nWe have a potion to make!" }, -- ?
    { id = 97292, name = "Unending Torment (5/5)", level = 21, minLevel = 16, requires = { 97291 }, faction = "Horde", giver = "Master Apothecary Faranell", start = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, finish = { npc = "Master Apothecary Faranell", area = 1497, x = 48.4, y = 69.4 }, objective = "Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell.", desc = "I have concocted a lovely serum that our new guest is sure to find quite... stimulating.\n\nTake this. Feed it into the workings dripping from above him. Let's see if we can't show him why it's in his best interest to serve loyally.\n\nAnd try not to drop it. I can't afford a new assistant." }, -- ?
})

ns.AddQuests("exw", {
    { id = 469, name = "Daily Delivery", level = 21, minLevel = 18, faction = "Alliance", giver = "Einar Stonegrip", start = { npc = "Einar Stonegrip", area = 11, x = 49.8, y = 39.4 }, finish = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, objective = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.", desc = "Greetings, traveler!\n\nDon't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax.\n\nNow, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner?\n\nI'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible." }, -- ? (extra/series)
    { id = 471, name = "Apprentice's Duties", level = 26, minLevel = 18, requires = { 484 }, faction = "Alliance", giver = "James Halloran", start = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, finish = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, steps = { { name = "Giant Crocolisk Skin", area = 11, x = 20.9, y = 24.1 } }, objective = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.", desc = "I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight.\n\nMidwife says he might pull through, but in the meantime I still need my skins!\n\n...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels." }, -- ? (extra/series)
    { id = 484, name = "Young Crocolisk Skins", level = 22, minLevel = 18, requires = { 469 }, faction = "Alliance", giver = "James Halloran", start = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, finish = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, steps = { { name = "Young Crocolisk Skin", area = 11, x = 15.4, y = 49.5 } }, objective = "Obtain 6 Young Crocolisk Skins for James Halloran in Menethil Harbor.", desc = "I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world.\n\nMet Einar? He's one of the hunters that brings crocolisk skins in for me.\n\nI'm a bit short on the softer skins that come off crocolisk young.\n\nBeing that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the waters right outside of town." }, -- ? (extra/series)
    { id = 95646, name = "Horrors in the Highland", level = 31, minLevel = 24, faction = "Alliance", giver = "Rethiel the Greenwarden", start = { npc = "Rethiel the Greenwarden", area = 11, x = 56.2, y = 40.4 }, finish = { npc = "Rethiel the Greenwarden", area = 11, x = 56.2, y = 40.4 }, dungeon = "exw", objective = "Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands.", desc = "These brackish wetlands hold a greater well of unsalted southern waters. It pains me, yet within my roots I sense a corruption seeping through that mountain gully.\n\nThe creatures, like those in our lowlands, react more bitterly to the taint. Lacking the sea's hardening salt since life's dawn, they have little strength against such evil.\n\nGo to those highlands, and bring me the Highland Horror's root core." }, -- Dungeon
    { id = 95647, name = "Lost in the Thicket Things", level = 31, minLevel = 24, faction = "Alliance", giver = "Caitlin Grassman", start = { npc = "Caitlin Grassman", area = 11, x = 11.8, y = 58.6 }, dungeon = "exw", objective = "Find Ardin Grassman in the Excavation Sites.", desc = "My husband, Ardin, has a rare gift for sensing nature. He'll scale any peak to gather the herbs and flowers I need for my alchemy, keeping our shelves and pantry stocked.\n\nBut I fear he's wandered into trouble. An excavation crew passed through seeking supplies. They spoke, among other things, of towering grasses unlike anything they'd ever seen. Those were what he told me he had to go see for himself. He's been gone too long!\n\nIf you learn anything of him, I'd be grateful." }, -- Dungeon
    { id = 95663, name = "Dragonmaw Rumors", level = 31, minLevel = 24, giver = "Zaruk", start = { npc = "Zaruk", area = 45, x = 74.4, y = 35.6 }, finish = { npc = "Deathstalker Agent", area = 11, x = 51.4, y = 59.2 }, dungeon = "exw", desc = "The Dragonmaw are a formidable clan.\n\nThey're known for binding magic strong enough to make dragons serve, and rumor claims they're preparing some display of it in the Wetlands. Whether truth or bluster, the Deathstalkers can't act on half-formed whispers. Titanic winds carried only that much to me.\n\nA deathstalker agent needs a hand in the hills above the Dragonmaw encampment. Meet her there. She'll reveal the next steps." }, -- Dungeon
    { id = 95664, name = "Elder Knowledge", level = 31, minLevel = 24, faction = "Horde", finish = { npc = "Bashana Runetotem", area = 1638, x = 70.8, y = 33.8 }, dungeon = "exw", objective = "Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it.", desc = "This unusual composite shard scatters light like a living prism. Its nature is uncertain, but its power feels ancient. The most knowledgeable minds for artifacts of this bygone age must reside on the Elder rise in Thunder Bluff." }, -- Dungeon
    { id = 95682, name = "Open the Maw", level = 31, minLevel = 24, requires = { 95663 }, giver = "Deathstalker Agent", start = { npc = "Deathstalker Agent", area = 11, x = 51.4, y = 59.2 }, finish = { npc = "Deathstalker Agent", area = 11, x = 51.4, y = 59.2 }, dungeon = "exw", objective = "Slay the Dragonmaw forces within the Excavation Site and return to the Deathstalker Agent outside with anything you recover.", desc = "Dragonmaw. <She lets out a dry, amused scoff.>\n\nThe remnants of the dragon-wrangling clan think they've found something that could lead to them rising to their former power. In the eyes of whom... their false warchief?\n\nClear out their ragtag clan within the Excavation Sites so our Deathstalkers can move in undetected.\n\nIf the Dragonmaw carry anything of note upon them, return it to me--this information must stay between us and our royal command." }, -- Dungeon
    { id = 95697, name = "Changing Tastes", level = 31, minLevel = 24, faction = "Horde", giver = "Borstan", start = { npc = "Borstan", area = 1637, x = 57.4, y = 53.4 }, finish = { npc = "Borstan", area = 1637, x = 57.4, y = 53.4 }, dungeon = "exw", objective = "Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat.", desc = "Zamja tells me we need more homestyle cooking.\nIf we start selling raptor, she thinks it'll draw in customers who don't usually visit Borstan's Firepit.\n\nHer idea is not so bad. But I want something that rises above the smells of our birth villages. We're in Orgrimmar! Borstan should serve a grand take on their familiar favorites.\n\nA hunter recently came back from the Wetlands with a giant talon from the thicket raptors in the Excavation Sites.\n\nUp for a job?" }, -- Dungeon
    { id = 95737, name = "Seeking Caitlin", level = 31, minLevel = 24, giver = "Llana", start = { npc = "Llana", area = 331, x = 35, y = 48.4 }, finish = { npc = "Caitlin Grassman", area = 11, x = 11.8, y = 58.6 }, dungeon = "exw", desc = "From time to time, I correspond with others in my craft--herbalists or eccentrics who study rare plants and local oddities. We trade discoveries, and sometimes warnings of what lies ahead.\n\nOne alchemist in the Wetlands wrote of an excavation team her husband was part of, uncovering signs of a long-lost primordial grass... but she never sent word of its abundance or accessibility.\n\nIf you can, check on Caitlin Grassman in Menethil Harbor." }, -- Dungeon
    { id = 95772, name = "Songblade Search", level = 31, minLevel = 24, giver = "Dorin Songblade", start = { npc = "Dorin Songblade", area = 44, x = 25.7, y = 46.6 }, dungeon = "exw", desc = "Me brother tried draggin' me off tae the Wetlands with some diggin' crew out o' Loch Modan. Said they were headin' into hills no dwarf's ever set boot in for some sort o' excavation.\n\nAye, I'd 'ave gone, if I wasn't already behind on this pile o' girdles I've got to refit.\n\nDaewyn normally writes after he sends off, though. Haven't heard a thing, gives me a strange feelin' this time.\n\nIf yer marchin' that way, mind checking in on me brother?" }, -- Dungeon
    { id = 95795, name = "Fallen in the Fen", level = 31, minLevel = 24, faction = "Alliance", finish = { npc = "Dorin Songblade", area = 44, x = 25.7, y = 46.6 }, dungeon = "exw", desc = "<You cover the dwarf's body with his cloak.>\n\nTravel to Lakeshire and personally inform Dorin Songblade what became of his brother within the Excavation Sites." }, -- Dungeon
    { id = 95809, name = "Heartwoven", level = 31, minLevel = 24, requires = { 95647 }, faction = "Alliance", finish = { npc = "Caitlin Grassman", area = 11, x = 11.8, y = 58.6 }, dungeon = "exw", objective = "Return to Caitlin Grassman in Menethil Harbor.", desc = "I need a moment to rest before I find my own way out.\n\n<He pulls some reeds from his pack and quickly braids and bends them into a heart.>\n\nTake this, and bring it back to Caitlin. Let her know I'll be home soon! Now that we have a path cleared out thanks to you, I'll gather my bushels and follow your trail.\n\nThank you." }, -- Dungeon
    { id = 95810, name = "Lost Relic Carry", level = 31, minLevel = 24, faction = "Alliance", finish = { npc = "Prospector Whelgar", area = 11, x = 38.8, y = 52.2 }, dungeon = "exw", objective = "Bring the Titan Relic to Prospector Whelgar in the Wetlands excavation site.", desc = "You pick up a fractured piece of the rock-mech automaton. It has a texture unlike anything you've touched before, a composite material of unknown makeup. This is certainly bound to be more 'device' than 'debris.'\n\nProspector Whelgar himself at his excavation site might have something useful to share about the relic." }, -- Dungeon
    { id = 98815, name = "Highland Hides", level = 28, minLevel = 24, giver = "James Halloran", start = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, finish = { npc = "James Halloran", area = 11, x = 8.6, y = 55.6 }, objective = "Return 4 Thicket Raptor Hides to James Halloran, the tanner, in Menethil Harbor.", desc = "The Highlands are host to ruins of some sort, secrets now being explored by an expedition team. What I know is that they've got their own wildlife and beasts lurking in that mountain marshland. How about you take a foray in there with some well-equipped friends, and we work a trade?\n\nI don't care if they're hiding, I want their hides! Bring me the skins from four of the Thicket Raptors, I'll have a trade worked out for you to make it worth it." }, -- ?
    { id = 98823, name = "Earthen Echo", level = 31, minLevel = 24, requires = { 95664 }, faction = "Horde", giver = "Bashana Runetotem", start = { npc = "Bashana Runetotem", area = 1638, x = 70.8, y = 33.8 }, finish = { npc = "Muln Earthfury", area = 215, x = 34.9, y = 31.9 }, dungeon = "exw", objective = "Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore.", desc = "Truly, this is a fascinating object.\n\nIt shows indications of being much more than a mere carving or sculpture.\n\nWhile our elders may be interested in observing this artifact, the Earthen Ring are who would carry the most wisdom for our buried ruins and forgotten lands. Seek out Muln Earthfury, a direct approach is fitting for the gravity of what you carry.\n\nYou can find him and other elders of the Earthen Ring council at the Skywatcher Plateau in northwest Mulgore." }, -- Dungeon
    { id = 98824, name = "Prehistoric Prism", level = 31, minLevel = 24, requires = { 95810 }, faction = "Alliance", giver = "Prospector Whelgar", start = { npc = "Prospector Whelgar", area = 11, x = 38.8, y = 52.2 }, finish = { npc = "High Explorer Magellas", area = 1537, x = 69.6, y = 18.6 }, dungeon = "exw", objective = "Bring the Titan Relic to High Explorer Magellas in Ironforge's Hall of Explorers.", desc = "With titan-like inscriptions like that on its facets, nothing less than Ironforge's Hall of Explorers is the right place to bring it.\n\nI'd like to think that you'll be noted in the history for it in the catalogue -- \"Recovered by <name>! Authenticated by Prospector Whelgar...\" Ah, I'm gettin' meself carried away.\n\nHigh Explorer Magellas will receive you, and given the exquisite nature of what you carry, will surely be most generously appreciative should you donate it to the museum.\n\nGood find!" }, -- Dungeon
})

ns.AddQuests("dal", {
    { id = 92432, name = "An Alarming Request", level = 33, minLevel = 30, faction = "Alliance", giver = "Emissary Jacques", start = { npc = "Emissary Jacques", area = 267, x = 48.3, y = 60.1 }, finish = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, desc = "I bring ill tidings from Dalaran. Something has disrupted our ley lines, causing erratic and destructive behavior from our constructs in the city.\n\nWe know not yet what is causing this mayhem. The high council has ordered us to keep this matter private so as to not bring shame to our order. But we cannot keep up this charade forever. The city is being overrun as we speak!\n\nArchmage Modera has dispatched me to solicit outside aid. Seek her image out near Dalaran beside Lordamere Lake." }, -- ? (extra/series)
    { id = 92434, name = "Blood in the Streets", level = 34, minLevel = 30, faction = "Horde", giver = "Magus Wordeen Voidglare", start = { npc = "Magus Wordeen Voidglare", area = 267, x = 61.6, y = 20.8 }, finish = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, objective = "Find a way into Dalaran along the Lordamere Lake.", desc = "Whatever caused Dalaran's barrier to lower has left the city in turmoil. With you having dealt with their patrols, there is no better time than now to make our way inside and discover their secrets.\n\nTake the key you found at the internment camp and seek out their sewers along the northern border of the city. With luck, those mages had no reason to put a ward over such a... disagreeable point of entry." }, -- ? (extra/series)
    { id = 92456, name = "A Green Sample", level = 33, minLevel = 24, faction = "Alliance", giver = "Shylamiir", start = { npc = "Shylamiir", area = 1519, x = 31.4, y = 63 }, dungeon = "dal", objective = "Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City.", desc = "If you're going to bother me you can at least make yourself useful. I have an errand I need run.\n\nFor a city of mages, Dalaran has a surprising interest in botany. The Kirin Tor keep to themselves, but I would love a sample of their mana-infused vegetation.\n\nYou're clearly someone who is comfortable being where people don't want you, maybe you could find a way into the city. If you do, bring me back whatever is growing in their central garden." }, -- Dungeon
    { id = 92457, name = "Starving Arcane", level = 33, minLevel = 24, giver = "Image of Archmage Modera", start = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, dungeon = "dal", objective = "Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran.", desc = "The breach has affected many of our factotums and enchantments throughout the city, including many that are seeing to our defenses. This fragmented arcane energy has spoken to rogue elementals who seek to saturate themselves in this free flowing magic.\n\nWhile we are busy tending to the wards and other major incidents, it would be a favor to the Kirin Tor if you could cull this elemental throng." }, -- Dungeon
    { id = 92458, name = "Heart of Disruption", level = 33, minLevel = 24, requires = { 92432 }, faction = "Alliance", giver = "Image of Archmage Modera", start = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, dungeon = "dal", objective = "Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran.", desc = "Whatever disturbed the ley lines, it started at the top of the Violet Citadel. A thunderous crash rang out from the parlors above, and now we are overrun with rampant arcane power. It's taking all we have just to keep the wards in place.\n\nWe cannot afford to stall any longer. We need help.\n\nThe Kirin Tor are busy inside, but you will still need a less public approach to gain entry. Take this key and meet me in the citadel once you've made your way into the city. We must put an end to this disruption." }, -- Dungeon
    { id = 92489, name = "Power Overwhelming", level = 33, minLevel = 24, faction = "Alliance", giver = "High Sorcerer Andromath", start = { npc = "High Sorcerer Andromath", area = 1519, x = 48.8, y = 87.6 }, dungeon = "dal", objective = "Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City.", desc = "The Kirin Tor have long been allies of the Alliance. With the destruction of their city at the hands of the arch demon Archimonde, the once proud city of mages has now become reclusive and distrusting of outsiders.\n\nIn recent years they have begun reconstruction efforts to bring the city of Dalaran back to its former glory. However, reports show they are struggling to contain an outbreak of wayward arcane energies.\n\nWe must help them disperse these attacks lest we lose one of our most powerful allies." }, -- Dungeon
    { id = 96984, name = "Heart of Disruption", level = 33, minLevel = 24, requires = { 92434 }, faction = "Horde", giver = "Image of Archmage Modera", start = { npc = "Image of Archmage Modera", area = 130, x = 68.6, y = 45.2 }, dungeon = "dal", objective = "Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", desc = "You may not have our best interests at heart, but I won't deny an extra pair of hands. And if Dalaran falls, it takes everything with it--including your Undercity.\n\nSo, your benefactor wants in? Fine. I'll imbue your key to work past my wards so you can enter the city. Once you're in, meet me at the Violet Citadel where this all began. With everything going on the Kirin Tor will be too busy to stop you.\n\nScavenge what you will, but whatever happens, our first priority is to prevent a catastrophe." }, -- Dungeon
    { id = 96986, name = "The Grave Knight", level = 33, minLevel = 24, faction = "Horde", giver = "Melisara", start = { npc = "Melisara", area = 267, x = 62.6, y = 20.6 }, dungeon = "dal", objective = "Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill.", desc = "Within the underbelly of the mage city to the north is a traitor to our kind. A necromancer of disturbing talent. He raises an army of undeath right under the Kirin Tor's nose.\n\nI care not for the fate of the mage city, <name>, but this grave knight spits in the face of everything we Forsaken stand for. Put an end to him. Show him no one is beyond the reach of the Dark Lady." }, -- Dungeon
    { id = 96987, name = "Opportunistic Education", level = 33, minLevel = 24, faction = "Horde", dungeon = "dal", objective = "Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance.", desc = "Well if it ain't a like-minded entrepreneur. Sneakin' into Dalaran durin' such troublesome times? Tsk tsk.\n\nMy kinda <race>!\n\nWhile our mage friends here are occupied, maybe we could find ourselves some 'misplaced' treasures. They gots whole libraries dedicated to fancy arcane magics. If you could bring me one of their secret tomes, I could sell it for a pretty penny. Split the profits with ya.\n\nHey hey don't look at me like that. You ain't exactly here on a field trip yourself. You want in or what?" }, -- Dungeon
    { id = 96988, name = "Source of Power", level = 33, minLevel = 24, faction = "Horde", giver = "Doctor Martin Felben", start = { npc = "Doctor Martin Felben", area = 1497, x = 46.6, y = 74.4 }, dungeon = "dal", objective = "Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity.", desc = "With the city of Dalaran under siege by their own constructs, this is the perfect opportunity to, let's say, borrow a few samples.\n\nImagine an army of arcane-powered abominations. The Dark Lady would have no choice but to recognize my alchemical prowess. Maybe even grant me head of the Royal Apothecary Society?\n\nGo to the city and find the constructs' cores. They are unlikely to give them willingly, so do what you must." }, -- Dungeon
})
